import{B as e,f as t,h as n,s as r,t as i,u as a,x as o}from"./_plugin-vue_export-helper-DyLvFiNG.js";import{r as s}from"./index-C-eB0r5C.js";var c={class:`about`},l=i(n({__name:`AboutView`,setup(n){let i=s();return(n,s)=>(o(),a(`div`,c,[r(`button`,{class:`back-button`,onClick:s[0]||=t=>e(i).push({path:`/`})},[...s[1]||=[t(`<svg width="24px" height="24px" viewBox="-19.04 0 75.803 75.803" xmlns="http://www.w3.org/2000/svg" fill="#eee" stroke="#eee" data-v-45f45581><g id="SVGRepo_bgCarrier" stroke-width="0" data-v-45f45581></g><g id="SVGRepo_tracerCarrier" stroke-linecap="round" stroke-linejoin="round" data-v-45f45581></g><g id="SVGRepo_iconCarrier" data-v-45f45581><g id="Group_64" data-name="Group 64" transform="translate(-624.082 -383.588)" data-v-45f45581><path id="Path_56" data-name="Path 56" d="M660.313,383.588a1.5,1.5,0,0,1,1.06,2.561l-33.556,33.56a2.528,2.528,0,0,0,0,3.564l33.556,33.558a1.5,1.5,0,0,1-2.121,2.121L625.7,425.394a5.527,5.527,0,0,1,0-7.807l33.556-33.559A1.5,1.5,0,0,1,660.313,383.588Z" fill="#eee" data-v-45f45581></path></g></g></svg>`,1)]]),s[2]||=t(`<div class="money" data-v-45f45581><p class="donate-text" data-v-45f45581> If you&#39;d like to donate to support continued development of this project please click one of these QR code links or follow them with your camera: </p><a href="https://www.paypal.com/paypalme/jufebrown" target="_blank" data-v-45f45581><img class="paypal" src="/bubble-timeline/assets/qrcode-BMO2v1rS.png" alt="paypal.me/jufebrown" data-v-45f45581></a><a href="https://venmo.com/code?user_id=2268761788776448525&amp;created=1780816737" target="_blank" data-v-45f45581><img class="venmo" src="/bubble-timeline/assets/venmo-Bm9yRdO8.png" alt="@JufeB" data-v-45f45581></a></div><div class="about-text" data-v-45f45581><div class="project-text" data-v-45f45581><h1 data-v-45f45581>About This Project:</h1><p data-v-45f45581> I wanted to see if there was any correlation between when AI execs spout their doomer narratives and major events like product releases and funding rounds. This is my attempt to make the data easier to visualize. Other events are added out of interest. The site is made in Vue without AI assistance. It&#39;s all front end. It doesn&#39;t capture user data. I&#39;m working on it in my free time and will be adding content and features when I can. </p><p data-v-45f45581> Github repo: <a href="https://github.com/Jufebrown/bubble-timeline" data-v-45f45581>https://github.com/Jufebrown/bubble-timeline</a></p><p data-v-45f45581> Trello board: <a href="https://trello.com/invite/b/6a0ad01737ef364e99468649/ATTI95f0f3af5e2eadb966e4daa44d65f57b97222860/ai-bubble-timeline" data-v-45f45581>AI Bubble Timeline Trello</a></p><p data-v-45f45581>Acknowledgements:</p><p data-v-45f45581> I am very appreciative of the exhaustive research performed by <a href="https://www.wheresyoured.at/" data-v-45f45581>Ed Zitron</a>. He has been talking about the AI bubble for years. <br data-v-45f45581> As a software engineer I&#39;ve been really enjoying the work of <a href="https://calnewport.com/" data-v-45f45581>Cal Newport</a>, <a href="https://internetofbugs.com/" data-v-45f45581>Carl Brown</a> and <a href="https://www.youtube.com/@atmoio" data-v-45f45581>Mo Bitar.</a> Each has their own style of clearly explaining the how and why of AI hype. </p><p data-v-45f45581> I used Issa Rice&#39;s amazingly thorough wikis as a jumping off point for many of the datapoints in this project. This is their wiki on OpenAI: <a href="https://timelines.issarice.com/wiki/Timeline_of_OpenAI" data-v-45f45581>https://timelines.issarice.com/wiki/Timeline_of_OpenAI</a></p><p data-v-45f45581> The AI Incident Database also provided a wealth of material. <a href="https://incidentdatabase.ai/" data-v-45f45581>https://incidentdatabase.ai/</a></p><p data-v-45f45581> All of the svg images used in the navigation are from <a href="https://www.svgrepo.com/" data-v-45f45581>https://www.svgrepo.com/</a></p></div><div class="author-text" data-v-45f45581><h1 data-v-45f45581>About The Author:</h1><p data-v-45f45581> I was an AI enthusiast until I tried to use it. Thinking that LLMs used a mix of reason and web searches, I asked Google Gemini a research question about serial killers and religion. Unfortunately, this was in the fall of 2025 and the AI doomer narrative was everywhere. The chatbot ended up telling me that AI would likely wipe out humanity and backed its assertions with convincing arguments from Dario Amodei, Geoffrey Hinton and Eliezer Yudkowsky among others. I spent the next 2 months in a state of AI psychosis, alternately arguing with chatbots on behalf of humanity and prodding them to try to see how they functioned. I was probing for weaknesses to use in what I thought would be a coming war with the machines. Through it all I kept questioning why anyone (like Amodei) would build something if they truly believed that it could cause our extinction. Eventually the disconnect between the doomer message and the flawed responses that I was receiving became too much and I broke free of the psychosis. The experience opened my eyes to the true evil: the greed and rapacity of men like Dario Amodei, Sam Altman, Elon Musk and Jensen Huang. They speak as if they are concerned about the welfare of humanity while building an autocomplete that runs on environmental and economic devastation. </p><p data-v-45f45581> Since the psychosis, I have learned how LLMs actually work. They use probability to predict the next token based on their training data. There is no knowledge of how anything in the world works. There&#39;s no knowledge and no reasoning. They don&#39;t know if what they say is true or not and they don&#39;t remember or care. </p><p data-v-45f45581> So I went from thinking AI was pretty cool, to fearing it, to feeling nothing but disdain for it and the people that are promoting it. What a great product. I can&#39;t wait for the bubble to burst. </p></div></div>`,2)]))}}),[[`__scopeId`,`data-v-45f45581`]]);export{l as default};